import{_ as a,c as n,o as e,ag as p}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Proxmox-Backup Restore","description":"","frontmatter":{"title":"Proxmox-Backup Restore"},"headers":[],"relativePath":"server-guides/proxmox-backup-restore.md","filePath":"server-guides/proxmox-backup-restore.md","lastUpdated":null}'),r={name:"server-guides/proxmox-backup-restore.md"};function l(i,s,t,o,c,u){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="proxmox-backup-restore" tabindex="-1">Proxmox-Backup Restore <a class="header-anchor" href="#proxmox-backup-restore" aria-label="Permalink to &quot;Proxmox-Backup Restore&quot;">​</a></h1><h2 id="proxmox-backup-and-restore" tabindex="-1">Proxmox Backup and Restore <a class="header-anchor" href="#proxmox-backup-and-restore" aria-label="Permalink to &quot;Proxmox Backup and Restore&quot;">​</a></h2><p>This guide provides options for consistently backing up a server, instructions for restoring from backups, and best practices for testing backups prior to needing them.</p><p>Back to [## Assumptions This guide focuses on Proxmox servers and assumes:</p><ul><li><p>A directory is established on the server for backups. Example: <code>/datadrive/Backups/</code></p></li><li><p>Services run within containers and VMs on the Proxmox server (host).</p></li><li><p>SSH keys have been established and copied into each VM and container. Refer to the SSH Keys](/server-guides/) guide for more on SSH key generation and usage.</p></li></ul><p>For specific service guides, see:</p><ul><li><a href="/infrastructure/authentik-backup.html">Backup</a></li></ul><h3 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># /usr/local/bin/proxmox-backup.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Define variables</span></span>
<span class="line"><span>BACKUP_DIR=&quot;/datadrive/Backups&quot;</span></span>
<span class="line"><span>VZ_DIR=&quot;/var/lib/vz/dump&quot;</span></span>
<span class="line"><span>BACKUP_REMOTE=&quot;pcloud:Backups/Server-Backups&quot;</span></span>
<span class="line"><span>VZ_REMOTE=&quot;pcloud:Backups/Server-Backups/VZDUMPS&quot;</span></span>
<span class="line"><span>LOCAL_BACKUP_DIR=&quot;/datadrive/Backups&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Authentik variables</span></span>
<span class="line"><span>AUTHENTIK_REMOTE_USER=&quot;root&quot;</span></span>
<span class="line"><span>AUTHENTIK_REMOTE_HOST=&quot;192.168.4.134&quot;</span></span>
<span class="line"><span>AUTHENTIK_REMOTE_BACKUP_DIR=&quot;/home/authentik/authentik/authentik_backups&quot;</span></span>
<span class="line"><span>TIMESTAMP=$(date +&quot;%Y%m%d%H%M%S&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Ensure remote backup directory exists</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST &quot;mkdir -p $AUTHENTIK_REMOTE_BACKUP_DIR&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Backup PostgreSQL Database</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST &quot;docker exec -i authentik-postgresql-1 /usr/local/bin/pg_dump --username authentik authentik &gt; $AUTHENTIK_REMOTE_BACKUP_DIR/postgres-back&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Save Redis Database</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST &quot;docker exec -i authentik-redis-1 redis-cli save&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Copy Redis Dump</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST &quot;docker cp authentik-redis-1:/data/dump.rdb $AUTHENTIK_REMOTE_BACKUP_DIR/redis-backup-$TIMESTAMP.rdb&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Create Tarball of Necessary Files</span></span>
<span class="line"><span>ssh $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST &quot;tar czvf $AUTHENTIK_REMOTE_BACKUP_DIR/authentik-backup-$TIMESTAMP.tar.gz -C /home/authentik/authentik authentik docker-compose.yml certs&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Sync from Authentik server to Proxmox backup</span></span>
<span class="line"><span>rsync -avz --progress $AUTHENTIK_REMOTE_USER@$AUTHENTIK_REMOTE_HOST:$AUTHENTIK_REMOTE_BACKUP_DIR $LOCAL_BACKUP_DIR/authentik_backups</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Remote backup completed successfully.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br></div></div><h3 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore&quot;">​</a></h3><p>Instructions for restoring from backup will depend on the specific service and the type of backup used. Refer to the <a href="/infrastructure/authentik-backup.html">Backup</a> or other service-specific guides for restoration steps.</p>`,11)])])}const m=a(r,[["render",l]]);export{d as __pageData,m as default};
